"""Ten original rumble problems to support seven rounds without repeated IDs."""
import random

def build_supplemental():
    rng=random.Random(20261014);bank=[]
    def nums(a):return ' '.join(map(str,a))+'\n'
    def add(side,level,title,statement,inp,constraints,out,tag,hint,solution,cases):
        bank.append(dict(id=f'E{side}-L{level}',set=8 if side=='A' else 9,level=level,title=title,statement=statement,input=inp,constraints=constraints,output=out,tag=tag,hint1=tag,hint2=hint,solution=solution,cases=cases,input_format=inp,sample_explanation=''))
    add('A',1,'상자의 총 무게','상자 N개에는 물건이 들어 있습니다. 각 상자의 물건 개수와 물건 하나의 무게가 주어집니다.\n\n상자 자체의 무게는 0입니다. 모든 상자의 물건 무게를 합한 값을 구하세요.','첫 줄 N. 다음 N줄에 개수 C와 개당 무게 W가 주어집니다.','1 ≤ N ≤ 100\n0 ≤ C, W ≤ 1000','총 무게 하나를 출력합니다.','반복문 / 누적 합','각 줄의 C × W를 더합니다.',"n=int(input())\ns=0\nfor _ in range(n):\n c,w=map(int,input().split());s+=c*w\nprint(s)",[f'{n}\n'+''.join(nums([rng.randrange(1001),rng.randrange(1001)]) for _ in range(n)) for n in [1,2,3,5,10,100]*3])
    add('B',1,'정해진 높이를 넘은 선수','선수 N명의 점프 높이가 주어집니다. 기준 높이 K 이상을 기록한 선수 수를 구하세요.\n\n정확히 K인 선수도 성공으로 셉니다. 같은 높이를 기록한 선수들은 각각 따로 셉니다.','첫 줄 N K. 다음 줄에 높이 N개가 공백으로 주어집니다.','1 ≤ N ≤ 100\n0 ≤ K, 높이 ≤ 1000','성공한 선수 수를 출력합니다.','조건문 / 개수 세기','높이가 K 이상인 원소마다 1을 더합니다.',"n,k=map(int,input().split())\na=list(map(int,input().split()))\nprint(sum(v>=k for v in a))",[f'{n} {k}\n'+nums([k]*(n//2)+[rng.randrange(1001) for _ in range(n-n//2)]) for n in [1,2,5,30,100] for k in [0,500,1000]])
    add('A',2,'연속된 경보','대문자 알파벳 문자열을 왼쪽부터 읽습니다. 같은 문자가 끊기지 않고 연속한 구간을 경보 구간이라고 합니다.\n\n가장 긴 경보 구간의 길이를 구하세요. 떨어져 있는 같은 문자 구간을 합치지 않습니다.','한 줄에 문자열 S가 주어집니다.','1 ≤ |S| ≤ 1000\n문자는 A~Z','가장 긴 연속 구간 길이를 출력합니다.','문자열 / 연속 구간','직전 문자와 같으면 현재 길이를 늘리고 다르면 1로 초기화합니다.',"s=input().strip()\nbest=run=1\nfor i in range(1,len(s)):\n run=run+1 if s[i]==s[i-1] else 1\n best=max(best,run)\nprint(best)",[s+'\n' for s in ['A','AAAA','ABAB','BAAAAB','ZZZZZZ','ABC']]+[''.join(rng.choice('ABC') for _ in range(n))+'\n' for n in [10,50,1000]*5])
    add('B',2,'돌아온 방문 번호','방문 번호 N개를 순서대로 기록했습니다. 처음 등장한 번호만 기록에 남기고, 이미 앞에서 등장한 번호는 삭제합니다.\n\n남길 번호의 개수를 구하세요. 삭제 여부는 등장 순서에 따르며, 번호의 크기와 관계없습니다.','첫 줄 N. 다음 줄에 정수 번호 N개.','1 ≤ N ≤ 1000\n1 ≤ 번호 ≤ 10000','남기는 번호 개수를 출력합니다.','집합 / 중복 제거','본 번호를 집합에 넣으면 집합 크기가 정답입니다.',"n=int(input())\nprint(len(set(map(int,input().split()))))",[f'{n}\n'+nums([rng.randrange(k)+1 for _ in range(n)]) for n in [1,2,10,100,1000] for k in [1,5,10000]])
    add('A',3,'창고 구간 재고','창고 N개가 일렬로 놓여 있습니다. 번호는 1부터 N까지입니다. 각 창고의 재고가 주어지고, Q개의 질문이 이어집니다.\n\n질문 L R마다 L번부터 R번까지 양 끝을 포함한 재고의 합을 구하세요. 질문 사이에 재고는 바뀌지 않습니다.','첫 줄 N Q. 다음 줄 재고 N개. 다음 Q줄에 L R.','1 ≤ N, Q ≤ 1000\n0 ≤ 재고 ≤ 10000\n1 ≤ L ≤ R ≤ N','질문 순서대로 합 Q개를 공백으로 구분하여 한 줄에 출력합니다.','누적 합 / 구간 합','앞에서부터 합을 저장하고 prefix[R] - prefix[L-1]로 질문에 답하세요.',"n,q=map(int,input().split())\na=list(map(int,input().split()));p=[0]\nfor v in a:p.append(p[-1]+v)\nans=[]\nfor _ in range(q):\n l,r=map(int,input().split());ans.append(p[r]-p[l-1])\nprint(*ans)",[f'{n} {q}\n'+nums(rng.randrange(10001) for _ in range(n))+''.join(nums(sorted([rng.randrange(n)+1,rng.randrange(n)+1])) for _ in range(q)) for n,q in [(1,1),(2,2),(10,20),(1000,1000)]*4])
    add('B',3,'연속 K일의 판매량','N일 동안 매일 판매한 물건 수가 주어집니다. 정확히 K일 연속한 기간 하나를 선택합니다.\n\n가능한 모든 기간 중 총판매량의 최댓값을 구하세요. 처음 날이나 마지막 날을 포함해도 됩니다.','첫 줄 N K. 다음 줄 판매량 N개.','1 ≤ K ≤ N ≤ 10000\n0 ≤ 판매량 ≤ 10000','K일 합의 최댓값을 출력합니다.','슬라이딩 윈도우','처음 K개의 합에서 빠지는 수를 빼고 새 수를 더하며 이동하세요.',"n,k=map(int,input().split())\na=list(map(int,input().split()));s=sum(a[:k]);best=s\nfor i in range(k,n):\n s+=a[i]-a[i-k];best=max(best,s)\nprint(best)",[f'{n} {k}\n'+nums(rng.randrange(10001) for _ in range(n)) for n in [1,2,10,100,10000] for k in sorted(set([1,n,n//2 or 1]))])
    add('A',4,'연결된 통신소','통신소는 1부터 N까지 번호가 붙어 있습니다. M개의 양방향 연결이 주어집니다.\n\nS번 통신소에서 시작하여 연결을 몇 번이든 따라갈 수 있을 때 도달 가능한 통신소의 수를 구하세요. 시작 통신소도 포함합니다. 같은 연결이 여러 번 나올 수 있습니다.','첫 줄 N M S. 다음 M줄에 양 끝 통신소 u v.','1 ≤ N ≤ 100\n0 ≤ M ≤ 500\n1 ≤ S, u, v ≤ N','도달할 수 있는 통신소 수를 출력합니다.','그래프 / BFS 또는 DFS','인접 리스트를 만들고 방문 배열로 한 번 방문한 정점을 다시 세지 않습니다.',"n,m,s=map(int,input().split());g=[[] for _ in range(n+1)]\nfor _ in range(m):\n u,v=map(int,input().split());g[u].append(v);g[v].append(u)\nseen={s};q=[s]\nfor u in q:\n for v in g[u]:\n  if v not in seen:seen.add(v);q.append(v)\nprint(len(seen))",[f'{n} {m} 1\n'+''.join(nums([rng.randrange(n)+1,rng.randrange(n)+1]) for _ in range(m)) for n,m in [(1,0),(5,0),(5,2),(10,10),(100,500)]*4])
    add('B',4,'탈출에 필요한 이동','N × N 지도에서 왼쪽 위 칸 (1,1)부터 오른쪽 아래 칸 (N,N)까지 이동합니다. 0은 이동할 수 있는 칸, 1은 벽입니다.\n\n한 번에 상하좌우 인접한 칸으로만 이동합니다. 지도 밖으로 나갈 수 없습니다. 도착까지 필요한 최소 이동 횟수를 구하세요. 시작 칸은 이동 횟수에 포함하지 않습니다. 도달할 수 없으면 -1입니다.','첫 줄 N. 다음 N줄에 0과 1로 된 길이 N 문자열. 행 안에는 공백이 없습니다.','1 ≤ N ≤ 30\n시작과 도착 칸은 0','최소 이동 횟수 또는 -1을 출력합니다.','격자 / BFS','시작 거리를 0으로 두고 큐로 확장하며 각 칸의 첫 방문 거리를 기록하세요.',"n=int(input());a=[input().strip() for _ in range(n)];d=[[-1]*n for _ in range(n)];d[0][0]=0;q=[(0,0)]\nfor r,c in q:\n for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:\n  nr,nc=r+dr,c+dc\n  if 0<=nr<n and 0<=nc<n and a[nr][nc]=='0' and d[nr][nc]<0:\n   d[nr][nc]=d[r][c]+1;q.append((nr,nc))\nprint(d[-1][-1])",[f'{n}\n'+'\n'.join(''.join('0' if (r,c) in [(0,0),(n-1,n-1)] else rng.choice('0001') for c in range(n)) for r in range(n))+'\n' for n in [1,2,3,10,30]*4])
    add('A',5,'오른쪽과 아래쪽의 배송비','N × N 칸에는 각 칸에 진입할 때 내는 배송비가 적혀 있습니다. 왼쪽 위에서 출발하여 오른쪽 아래에 도착합니다.\n\n이동은 오른쪽 또는 아래쪽으로 한 칸만 가능합니다. 시작 칸과 도착 칸의 비용도 냅니다. 가능한 경로의 비용 합 중 최솟값을 구하세요.','첫 줄 N. 다음 N줄에 각 행의 비용 N개가 공백으로 주어집니다.','1 ≤ N ≤ 50\n0 ≤ 비용 ≤ 1000','최소 비용 합을 출력합니다.','동적 계획법 / 격자','각 칸까지의 최소비용은 위와 왼쪽 최소비용 중 작은 것에 현재 비용을 더한 값입니다.',"n=int(input());a=[list(map(int,input().split())) for _ in range(n)];d=[[10**12]*n for _ in range(n)]\nfor r in range(n):\n for c in range(n):\n  if r==c==0:d[r][c]=a[r][c]\n  else:d[r][c]=min(d[r-1][c] if r else 10**12,d[r][c-1] if c else 10**12)+a[r][c]\nprint(d[-1][-1])",[f'{n}\n'+''.join(nums(rng.randrange(1001) for _ in range(n)) for _ in range(n)) for n in [1,2,3,10,50]*4])
    add('B',5,'한 번만 담는 보급품','보급품 N개를 배낭에 담으려고 합니다. 각 보급품에는 무게와 가치가 있으며 같은 보급품은 한 번만 담을 수 있습니다.\n\n배낭의 최대 무게 K를 넘지 않는 선택 중 가치 합의 최댓값을 구하세요. 아무것도 담지 않아도 됩니다. 무게가 K와 정확히 같아도 됩니다.','첫 줄 N K. 다음 N줄에 무게 W와 가치 V.','1 ≤ N ≤ 50\n0 ≤ K ≤ 500\n1 ≤ W ≤ 500\n0 ≤ V ≤ 1000','담을 수 있는 최대 가치 합을 출력합니다.','동적 계획법 / 0-1 배낭','용량별 최댓값 배열을 만들고 각 물건마다 용량을 큰 쪽부터 갱신하면 중복 선택을 막습니다.',"n,k=map(int,input().split());d=[0]*(k+1)\nfor _ in range(n):\n w,v=map(int,input().split())\n for j in range(k,w-1,-1):d[j]=max(d[j],d[j-w]+v)\nprint(d[k])",[f'{n} {k}\n'+''.join(nums([rng.randrange(500)+1,rng.randrange(1001)]) for _ in range(n)) for n,k in [(1,0),(2,500),(10,200),(50,500)]*5])
    return bank
